export type Faq = {
  id: string;
  question: string;
  answer: string;
  category?: string;
};

export type FaqTab = {
  id: string;
  title: string;
  value: string;
};

export type FaqSearch = {
  /** field: a search field above the questions */
  mode?: "none" | "field";
  /** accessible name and placeholder of the search field */
  label?: string;
  /** the text the questions are filtered by */
  query?: string;
};

export type FaqFilter = {
  /** categories: tabs above the questions */
  mode?: "none" | "categories";
  /** the category tabs */
  tabs?: FaqTab[];
  /** accessible name of the tabs */
  label?: string;
  /** the value of the chosen tab */
  category?: string;
};
